// Duo Custom Service Worker Extension (public/sw-custom.js)
// Imported by root /sw.js generated by vite-plugin-pwa.

// 1. Synchronously import authoritative OneSignal Service Worker SDK (v16)
// OneSignalSDK.sw.js is the sole authoritative handler for push events,
// background notification banners, vibration, icons, and click actions.
try {
  importScripts('https://cdn.onesignal.com/sdks/web/v16/OneSignalSDK.sw.js');
} catch (e) {
  console.warn('[SW] OneSignal worker SDK import notice:', e);
}

// 2. Safe top-level message listener for badge clearing and skip waiting
const handleWorkerMessage = (event) => {
  if (!event || !event.data) return;

  if (event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }

  if (event.data.type === 'CLEAR_BADGE_AND_NOTIFICATIONS') {
    event.waitUntil(
      (async () => {
        if ('clearAppBadge' in self.registration) {
          try {
            await self.registration.clearAppBadge();
          } catch (e) {}
        }
        try {
          const notifs = await self.registration.getNotifications();
          notifs.forEach((n) => n.close());
        } catch (e) {}
      })()
    );
  }
};

if ('onmessage' in self) {
  const prevOnMsg = self.onmessage;
  self.onmessage = (event) => {
    if (typeof prevOnMsg === 'function') prevOnMsg(event);
    handleWorkerMessage(event);
  };
} else {
  self.addEventListener('message', handleWorkerMessage);
}

// 3. Service worker activation & cache cleanup
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => {
      return Promise.all(
        keys.map((k) => {
          if (k.startsWith('av-cache-') && k !== 'av-cache-v4') {
            return caches.delete(k);
          }
        })
      );
    }).then(() => self.clients.claim())
  );
});

// 4. Ensure Firebase Auth handler URLs (/__/auth/...) bypass SW caching
self.addEventListener('fetch', (event) => {
  if (event.request.url.includes('/__/')) {
    return; // Direct network pass-through
  }
});
